// Un tipo de error propio: «class … extends Error» es una receta; las clases se estudian más adelante
class ErrorDeValidacion extends Error {
  constructor(campo, mensaje, opciones) {
    super(mensaje, opciones);
    this.name = "ErrorDeValidacion";
    this.campo = campo;
  }
}

function leerPeso(texto) {
  const n = Number(texto);
  if (texto.trim() === "" || Number.isNaN(n)) {
    throw new ErrorDeValidacion("peso", `«${texto}» no es un número`);
  }
  if (n < 0) throw new RangeError(`el peso no puede ser negativo (llegó ${n})`);
  return n;
}

function cargarLinea(texto) {
  try {
    return leerPeso(texto);
  } catch (e) {
    // envolvemos el error original para no perder la causa
    throw new Error("no se pudo cargar la línea de la planilla", { cause: e });
  }
}

for (const entrada of ["420", "38O", "-5"]) {
  try {
    console.log(entrada, "->", cargarLinea(entrada));
  } catch (e) {
    const c = e.cause;
    console.log(entrada, "->", e.message, "| causa:", c.name, "-", c.message,
      "| ¿es ErrorDeValidacion?", c instanceof ErrorDeValidacion, "| ¿es Error?", c instanceof Error);
  }
}

// Tres maneras de avisar «no pude» al leer un peso en kilos
// 1) Un valor especial: null. Barato, pero nadie te obliga a mirarlo
function pesoONull(texto) {
  const n = Number(texto);
  return texto.trim() === "" || Number.isNaN(n) ? null : n;
}
// 2) Un resultado con forma fija: ok y valor, o ok en false y el motivo (la idea de Result)
function pesoResultado(texto) {
  const n = Number(texto);
  if (texto.trim() === "" || Number.isNaN(n)) return { ok: false, error: `«${texto}» no es un número` };
  return { ok: true, valor: n };
}
// 3) Una excepción: el error sube solo hasta quien lo atrape
function pesoOExcepcion(texto) {
  const n = Number(texto);
  if (texto.trim() === "" || Number.isNaN(n)) throw new TypeError(`«${texto}» no es un número`);
  return n;
}

const textos = ["420", "38O"];

// 1) con null: si te olvidás del if, el null se cuela en la cuenta como si fuera 0
let total1 = 0;
for (const t of textos) total1 += pesoONull(t);
console.log("con null, sin mirar:", total1);

// 2) con resultado: la forma del dato te recuerda que hay dos casos
let total2 = 0;
for (const t of textos) {
  const r = pesoResultado(t);
  if (r.ok) total2 += r.valor;
  else console.log("resultado:", r.error);
}
console.log("con resultado:", total2);

// 3) con excepción: no hace falta mirar cada llamada, pero alguien tiene que atrapar
try {
  let total3 = 0;
  for (const t of textos) total3 += pesoOExcepcion(t);
  console.log(total3);
} catch (e) {
  console.log("con excepción:", e.name, "-", e.message);
}

