use std::num::ParseIntError;

fn kilos(texto: &str) -> Result<i32, ParseIntError> {
    let n = texto.parse::<i32>()?;
    Ok(n)
}

fn main() {
    match kilos("12kg") {
        Ok(n) => println!("n = {n}"),
        Err(e) => println!("error: {e}"),
    }
    println!("{:?}", kilos("1150"));
}

