// Dos llamadas simuladas (sin red real): una se cae y otra responde con error de servidor
const redCaida = () => Promise.reject(new TypeError("fetch failed"));
const servidorConError = () => Promise.resolve({ ok: false, status: 500 });
const servidorBien = () => Promise.resolve({ ok: true, status: 200 });

async function pedirPedido(llamada) {
  let r;
  try {
    r = await llamada();               // acá se rechaza si no hubo respuesta
  } catch (e) {
    return "sin conexión (" + e.message + "): conviene reintentar más tarde";
  }
  if (!r.ok) return "el servidor respondió " + r.status + ": no es un problema de red";
  return "pedido recibido";
}

for (const [nombre, llamada] of [["red caída", redCaida], ["servidor con error", servidorConError], ["todo bien", servidorBien]]) {
  console.log(nombre + " -> " + await pedirPedido(llamada));
}

